WHO_SUIC = src("src-who-suicide", "Suicide fact sheet", "World Health Organization", "https://www.who.int/news-room/fact-sheets/detail/suicide", 2025, note="Figures from search summaries of the 2025 fact sheet; page not opened.")
SWANNELL = src("src-swannell-nssi", "Prevalence of nonsuicidal self-injury in nonclinical samples: systematic review, meta-analysis and meta-regression", "Suicide and Life-Threatening Behavior (Swannell et al.), 44(3):273–303", "https://researchers.westernsydney.edu.au/en/publications/prevalence-of-nonsuicidal-self-injury-in-nonclinical-samples-syst/", 2014, seen=True)
LUNDORFF = src("src-lundorff-pgd", "Prevalence of prolonged grief disorder in adult bereavement: a systematic review and meta-analysis", "Journal of Affective Disorders (Lundorff et al.); PubMed 28167398", "https://pubmed.ncbi.nlm.nih.gov/28167398/", 2017, seen=True)
ACES = src("src-cdc-aces", "Prevalence of adverse childhood experiences among US adults (BRFSS 2015–2017)", "CDC / JAMA Pediatrics summary (PMC6248156)", "https://pmc.ncbi.nlm.nih.gov/articles/PMC6248156/", 2019, seen=True)
NCES = src("src-nces-bullying", "Bullying at school and electronic bullying", "National Center for Education Statistics (NCES) Fast Facts", "https://nces.ed.gov/fastfacts/display.asp?id=719", 2024, seen=True)
FLOOD = src("src-flood-ptsd", "Prevalence of post-traumatic stress disorder after flood: a systematic review and meta-analysis", "PubMed Central (PMC9259936)", "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9259936/", 2022, seen=True)
MHGAP = src("src-who-mhgap", "Mental Health Gap Action Programme (mhGAP)", "WHO Eastern Mediterranean Regional Office", "https://www.emro.who.int/mnh/mental-health-gap-action-programme/mhgap.html", seen=True)
MEYER = src("src-meyer-2003", "Prejudice, social stress, and mental health in lesbian, gay, and bisexual populations: conceptual issues and research evidence", "Psychological Bulletin (Meyer); PubMed 12956539", "https://pubmed.ncbi.nlm.nih.gov/12956539/", 2003, seen=True)
NICE158 = "src-nice-cg158"
ALT2SU = src("src-alt2su", "Alternatives to Suicide", "Wildflower Alliance", "https://wildfloweralliance.org/alternatives-to-suicide/", seen=True)
SAFE_MSG = ["Safe-messaging rules apply: no methods, no locations, no notes, no 'epidemic' framing.", "Illustrations show connection and daylight, never isolation or danger."]
HI = ["crisis-lines-global"]

CARDS.append(X("suicidal-thoughts-and-behavior", "Suicidal Thoughts and Behavior", "When you're thinking about ending your life", ["suicidal ideation", "suicide attempt", "suicidality"], "T14.91XA / T14.91XD (current) ; Z91.51 (history)",
 "Thoughts of ending your life, or having acted on them. Common, serious, survivable, and something you can talk about.",
 "Suicidal thoughts range from wishing you weren't here to making a plan or an attempt. They can come with depression, trauma, loss, pain, shame, or feeling like a burden, and sometimes without a clear reason. They're far more common than most people realise, and most people who have them do not die by suicide. Clinicians record them so that safety and support come first. Talking about it doesn't make it more likely; it makes help possible.",
 ["I didn't want to die. I wanted the pain to stop and couldn't see another door. Someone sat with me until I could.", "Saying it out loud to my sister was the scariest and most important sentence of my life.", "The thoughts still visit sometimes. Now they're a signal to reach out, not a secret to keep."],
 ["Thinking you'd be better off dead, or others would be better off without you", "Thinking about ways to end your life, or making a plan", "Feeling trapped, hopeless, or like a burden", "Withdrawing, giving things away, saying goodbye", "A sudden calm after a long low period; this can be a warning sign"],
 [{"myth": "Asking someone if they're suicidal might put the idea in their head.", "fact": "Research is clear: asking directly and calmly doesn't increase risk. It often brings relief and opens the door to help."},
  {"myth": "People who talk about it are just seeking attention.", "fact": "Most people who die by suicide gave some signal first. Talking about it is a reason to take someone seriously, not to dismiss them."},
  {"myth": "If someone has decided, nothing can stop them.", "fact": "Suicidal crises usually pass, often within hours. Support, time, and reducing access to means save lives. Most people who survive a crisis are glad they did."}],
 {"plain": "Suicidal thoughts are common: large surveys find a meaningful share of adults and teens have had them in the past year. Deaths are far rarer than thoughts, and most people who think about suicide recover.", "figure": "WHO estimates over 720,000 suicide deaths worldwide each year, the third leading cause of death at ages 15–29 (2021 data, 2025 fact sheet); past-year ideation in general-population surveys is many times higher than deaths", "source_ref": "src-who-suicide", "note": "Present with care; avoid 'epidemic' framing."},
 {"plain_summary": "Help works. Crisis lines, a trusted person, and emergency services get you through the acute hours. Safety planning, done with a clinician or a tool, lists your warning signs, coping steps, people to contact, and ways to make your environment safer. Treating what's underneath, such as depression, trauma, substance use, or pain, lowers risk over time, and some therapies (CBT for suicide prevention, DBT, CAMS) target suicidal thinking directly. Peer groups such as Alternatives to Suicide let people talk openly without judgement or forced intervention. Follow-up contact after a crisis matters.",
  "evidence_based_options": ["A safety plan made with a clinician or a trusted person", "Therapies that target suicidal thinking: CBT for suicide prevention, DBT, CAMS", "Treatment of underlying depression, trauma, substance use, or pain, with any medication prescribed and monitored by a doctor", "Reducing access to means, with support from people you trust"],
  "self_help_that_supports_care": ["Telling one person today; you don't have to carry it alone", "Keeping a crisis line number where you can see it", "Writing your own reasons for living and coping steps when you're calmer", "Peer support groups where suicidal thoughts can be spoken about honestly"],
  "guideline_refs": ["src-who-suicide"]},
 "If you're thinking about ending your life, please reach out now: call or text a crisis line from the strip below, tell someone near you, or go to an emergency department. If you're in immediate danger, call emergency services. If you're worried about someone else, ask them directly, stay with them, and help them connect to support.",
 "Wishing a hard situation would end, or wanting to escape, isn't the same as planning to die, though it's worth talking about. Self-harm without intent to die is covered on the next card. Grief and sadness are not suicidality.",
 "Suicidal crises pass. People who have been in the darkest place describe lives afterwards they couldn't have imagined from inside it. You are not a burden, and you are not alone.",
 ["nonsuicidal-self-injury", "major-depressive-disorder", "posttraumatic-stress-disorder", "borderline-personality-disorder", "alcohol-use-disorder", "grief-and-bereavement"],
 ["suicidal-ideation", "passive-vs-active-suicidal-ideation", "safety-plan", "crisis-plan", "crisis-line", "warning-signs", "safe-messaging", "suicide-attempt-survivor"],
 ["alt2su-wildflower-alliance", "nami-connection-and-helpline", "mind-side-by-side", "sane-forums-australia", "beyondblue-forums"],
 ("Soft line illustration of two people sitting on a bench at dawn, one with a hand on the other's shoulder, a phone between them, the sky lightening. Pastel sky blue and warm gold. No darkness, no isolation.", "Two people sit together on a bench at dawn, one with a hand on the other's shoulder."),
 [DSM_X, WHO_SUIC, ALT2SU], qs=["Open the WHO fact sheet to confirm current figures.", "Suicide-prevention specialist to review safe messaging."], sens="high", notes=SAFE_MSG, clin=True, card_type="clinical-focus",
 young="Teens may show it through irritability, risk-taking, or withdrawal rather than words. Adults: ask directly, listen without panic, and connect them to a youth crisis line or clinician the same day."))

CARDS.append(X("nonsuicidal-self-injury", "Nonsuicidal Self-Injury", "Hurting yourself on purpose to cope, without wanting to die", ["self-harm", "NSSI", "self-injury"], "R45.88 (current) ; Z91.52 (history)",
 "Deliberately hurting your own body to cope with overwhelming feelings, without intending to die.",
 "Nonsuicidal self-injury is hurting your own body on purpose, without wanting to die, usually to cope with feelings that feel unbearable: numbness, anger, shame, or overwhelming distress. It often brings short-term relief, which is why it repeats, and then guilt and secrecy. It usually starts in the early teens and is common. It isn't attention-seeking and isn't a suicide attempt, though it raises risk and deserves care. People learn other ways to cope, and they stop.",
 ["It was the only thing that made the noise in my head go quiet. Learning other ways to turn the volume down took time, and it worked.", "My mum found out and cried. Then she asked what I needed. That question mattered more than anything.", "I'm five years free of it. The urges fade. I promise they fade."],
 ["Deliberately injuring yourself to cope with distress, without intending to die", "Short-term relief followed by guilt, shame, or secrecy", "Hiding injuries; long sleeves in hot weather; avoiding activities", "Urges that rise with stress, conflict, or feeling numb", "Often alongside depression, anxiety, trauma, or eating difficulties"],
 [{"myth": "Self-harm is attention-seeking.", "fact": "Most people hide it carefully. It's a way of coping with pain, not a performance. If someone does show it, treat it as a request for help, which deserves a response."},
  {"myth": "Self-harm is a failed suicide attempt.", "fact": "Nonsuicidal self-injury is about coping, not dying. But it increases suicide risk over time, so it's taken seriously, with care rather than alarm."},
  {"myth": "Punishing or forcing someone to stop will fix it.", "fact": "Shame and control make it worse. Understanding what the self-injury does for the person, and building other ways to cope, is what helps."}],
 {"plain": "Roughly 1 in 6 teenagers and 1 in 20 adults have self-injured at some point, according to a large review. Many never tell anyone.", "figure": "Pooled lifetime prevalence 17.2% in adolescents, 13.4% in young adults, 5.5% in adults (meta-analysis, 2014)", "source_ref": "src-swannell-nssi"},
 {"plain_summary": "Therapy helps people understand what self-injury is doing for them and build other ways to handle the feelings. DBT skills (distress tolerance, emotion regulation) have the strongest evidence, especially for teens; CBT, family-based approaches, and treating underlying depression, trauma, or anxiety also help. Wound care without judgement matters. Harm-reduction approaches, used in some services, focus on safety while the person works toward stopping. Medication isn't a treatment for self-injury itself but may help co-occurring conditions, prescribed and monitored by a doctor.",
  "evidence_based_options": ["DBT or DBT skills groups, including adapted versions for adolescents", "CBT and family-based therapy", "Treatment of underlying depression, anxiety, trauma, or eating difficulties", "Non-judgemental medical care for injuries"],
  "self_help_that_supports_care": ["A list of things that delay or replace the urge: cold, movement, drawing, calling someone", "Telling one trusted person", "Tracking urges and triggers to find patterns", "Online recovery resources from universities and charities, not pro-self-harm spaces"],
  "guideline_refs": ["src-swannell-nssi"]},
 "If you're hurting yourself, you deserve support, not punishment. Talk to a doctor, school counsellor, or therapist, or contact a crisis or text line from the strip below. Seek urgent medical care for any injury that's deep, won't stop bleeding, or involves swallowing something. If you're also thinking about ending your life, reach out now.",
 "Tattoos, piercings, and body modification aren't self-injury. Risky behaviour like substance use isn't NSSI, though it may be a related way of coping. Self-injury with intent to die is a suicide attempt and handled as such.",
 "Self-injury is something people stop. With other ways to cope, the urges lose their grip, and the scars become part of a story of survival.",
 ["suicidal-thoughts-and-behavior", "borderline-personality-disorder", "major-depressive-disorder", "posttraumatic-stress-disorder", "nonsuicidal-self-injury-disorder", "anorexia-nervosa"],
 ["self-harm", "emotional-dysregulation", "dbt", "coping-skills", "harm-reduction", "safe-messaging"],
 ["cornell-self-injury-recovery-resources", "alt2su-wildflower-alliance", "mind-side-by-side", "sane-forums-australia"],
 ("Soft line illustration of a teenager holding a cold drink can against their wrist while sitting with a friend on the grass, a sketchbook open beside them, daylight. Pastel sky blue and mint. No injuries or scars shown.", "A teenager sits on the grass with a friend, holding a cold drink can, a sketchbook open beside them."),
 [DSM_X, SWANNELL, src("src-cornell-sirr", "Self-Injury & Recovery Resources (SIRR)", "Cornell University Bronfenbrenner Center", "https://selfinjury.bctr.cornell.edu/", seen=True)],
 qs=["Clinician to review safe-messaging wording."], sens="high", notes=SAFE_MSG + ["No descriptions of methods, tools, or wounds anywhere on the card."], clin=True, card_type="clinical-focus",
 young="Self-injury usually begins around 12 to 14. Adults who find out should stay calm, avoid punishment, ask what's going on underneath, and arrange support the same week."))

CARDS.append(X("grief-and-bereavement", "Grief and Bereavement", "Losing someone, and when grief needs extra support", ["uncomplicated bereavement", "prolonged grief disorder (a separate diagnosis)", "mourning"], "Z63.4",
 "The natural response to losing someone, which is not a disorder, and the signs that grief has become stuck.",
 "Grief is the natural response to losing someone or something important. It comes in waves: sadness, longing, numbness, anger, guilt, relief, trouble sleeping, even physical pain. There's no right timeline. The DSM lists bereavement as a focus of care, not a disorder, so people can get support without being labelled ill. In a minority, grief stays intensely stuck for a year or more and stops life moving; that's prolonged grief disorder, and it responds to specific therapy.",
 ["Eighteen months on, people had stopped asking. That was when I needed them most.", "I laughed at a funeral and felt like a monster. The counsellor said laughing and sobbing in the same hour is grief doing its job.", "Grief didn't get smaller. I got bigger around it."],
 ["Waves of sadness, longing, or numbness after a loss", "Trouble sleeping, eating, or concentrating", "Guilt, anger, relief, or feeling nothing, all normal", "Grief that's still intense and life-stopping after a year may need specific help", "Thoughts of wanting to join the person; please reach out"],
 [{"myth": "Grief follows five neat stages.", "fact": "The 'stages' were never meant as a map. Grief comes in waves, loops, and surprises, and that's normal."},
  {"myth": "You should be over it by now.", "fact": "There's no deadline. Most people carry grief for life and build life around it. Help is for when it's stuck, not for taking too long."},
  {"myth": "Grieving is depression.", "fact": "They can overlap, but grief usually keeps the capacity for warmth and good memories, and comes in waves tied to the person. Depression is flatter and more global."}],
 {"plain": "Everyone grieves. Around 1 in 10 bereaved adults develops prolonged grief that needs specific help, higher after sudden or violent losses.", "figure": "Prolonged grief disorder pooled prevalence 9.8% after non-violent bereavement (meta-analysis, 2017); 5%–16% depending on sampling (2024 update)", "source_ref": "src-lundorff-pgd"},
 {"plain_summary": "Most grief needs company, time, and permission, not treatment. Bereavement support groups and helplines, including ones for specific losses such as suicide, a child, or a partner, help people feel less alone. When grief is stuck and life-stopping after a year, prolonged grief therapy or grief-focused CBT works well. Depression, PTSD, or sleep problems that develop alongside grief are treated in their own right, with any medication prescribed and monitored by a doctor.",
  "evidence_based_options": ["Peer bereavement groups and helplines", "Prolonged grief therapy or grief-focused CBT when grief is stuck", "Treatment of co-occurring depression, PTSD, or insomnia", "Specialist support after suicide loss, child loss, or traumatic death"],
  "self_help_that_supports_care": ["Letting people help; saying what you need", "Keeping rituals and memories alive in your own way", "Sleep, food, and movement, even badly", "Groups with people who've had the same kind of loss"],
  "guideline_refs": ["src-lundorff-pgd"]},
 "Reach out to a bereavement service or counsellor if grief is still stopping you from functioning after many months, if you're using alcohol or drugs to cope, or if you feel you can't go on. If you're thinking about ending your life, please use the crisis strip now.",
 "Grief isn't depression, though both can be present. Anticipatory grief before a death, and grief for non-death losses like divorce or a diagnosis, are real and may need support too.",
 "People don't 'get over' loss. They learn to carry it, and most find, in time, that love and life can coexist with the missing.",
 ["prolonged-grief-disorder", "major-depressive-disorder", "posttraumatic-stress-disorder", "suicidal-thoughts-and-behavior", "adjustment-disorders"],
 ["grief", "disenfranchised-grief", "anticipatory-grief", "suicide-loss-survivor", "support-group"],
 ["cruse-bereavement-support", "reddit-r-griefsupport", "reddit-r-widowers", "alliance-of-hope", "sobs-uk", "the-dinner-party"],
 ("Soft line illustration of a person planting a small tree in a garden with a friend, a photograph propped on the fence, spring light. Pastel sky blue and sage.", "A person plants a small tree with a friend while a photograph rests on the fence."),
 [DSM_X, LUNDORFF], sens="elevated", notes=["Suicide-loss resources included; safe-messaging rules apply."], card_type="clinical-focus",
 young="Children grieve in bursts, playing one minute and sobbing the next, and often revisit the loss at each new stage of growing up. Honest, simple words and routine help more than protection from the truth.",
 cult="Mourning customs vary widely: how long, how loudly, who gathers, and what's said about the dead. None is more 'healthy' than another. Clinicians should ask about the family's traditions before judging grief as prolonged."))

CARDS.append(X("family-and-relationship-problems", "Family and Relationship Problems", "When the people closest to you are the source of the strain", ["relationship distress", "parent-child relational problem", "sibling relational problem", "family conflict"], "Z62.x / Z63.x",
 "Serious strain in a family or couple that affects wellbeing, recorded so it can be a focus of care.",
 "Conflict, distance, or upheaval in close relationships is one of the most common reasons people struggle, and the DSM gives it codes so clinicians can make it a focus of care without calling anyone ill. It covers things like parent-child conflict, high-conflict separation, a partner's illness, a family member's substance use, sibling estrangement, and relationship distress between partners. These problems can cause or worsen depression and anxiety, and treating the relationship often helps more than treating one person alone.",
 ["Every holiday was a minefield. Family therapy didn't fix my parents. It gave me a way to be in the room without losing myself.", "We weren't fighting about the dishes. We were fighting about being unseen. Couples therapy named it."],
 ["Ongoing conflict, coldness, or walking on eggshells at home", "Stress, low mood, or anxiety that tracks what's happening in the relationship", "Children caught in parental conflict or separation", "A family member's illness, substance use, or behaviour dominating family life"],
 [{"myth": "Family problems are private and should stay in the family.", "fact": "Family and couples therapy exist because outside help works. Keeping it private is often what keeps it stuck."},
  {"myth": "Couples therapy is for people about to break up.", "fact": "It works best earlier, when both people still want to make things better. It also helps couples separate well when that's the right outcome."}],
 {"plain": "Relationship and family strain is among the most common things people bring to therapy. There's no single prevalence figure; it affects most families at some point.", "figure": "n/a", "source_ref": "src-dsm"},
 {"plain_summary": "Couples therapy (such as emotionally focused therapy or behavioural couples therapy) and family therapy have strong evidence for relationship distress and for child and teen problems that are tangled up with family dynamics. Parenting programmes help with parent-child conflict. Mediation and co-parenting support help families through separation. Individual therapy helps people set boundaries, grieve, or decide what they want. Where there's abuse, safety comes before any joint therapy.",
  "evidence_based_options": ["Couples therapy (emotionally focused therapy, behavioural couples therapy)", "Family therapy and parenting programmes", "Mediation and co-parenting support during separation", "Individual therapy for boundaries, decisions, and recovery"],
  "self_help_that_supports_care": ["Parent and relationship helplines for a first conversation", "Learning about boundaries and repair, from reputable sources", "Keeping children out of adult conflict", "Noticing whether it's conflict or control; control is a safety issue"],
  "guideline_refs": []},
 "If relationship strain is affecting your mood, sleep, or health, or children are being hurt by conflict, a family or couples therapist, a parent helpline, or your doctor can help. If there's any violence, intimidation, or control, see the partner violence card and contact a domestic abuse service; joint therapy isn't safe in that situation.",
 "Ordinary disagreement isn't a relational problem. Abuse and coercive control are not 'relationship problems' and are covered on their own cards. A child's behaviour problem isn't automatically a family problem, though families are part of the solution.",
 "Relationships change when one person changes how they show up. Families repair, couples reconnect, and people find peace even where repair isn't possible.",
 ["partner-violence-and-adult-abuse", "child-abuse-and-neglect", "oppositional-defiant-disorder", "adjustment-disorders", "major-depressive-disorder"],
 ["family-therapy", "boundaries", "enmeshment", "codependency", "attachment"],
 ["family-lives-helpline", "youngminds-parents-helpline", "al-anon-electronic-meetings", "mind-side-by-side"],
 ("Soft line illustration of a family of four around a kitchen table with a board game, a therapist's leaflet on the fridge, warm evening light. Pastel sky blue and apricot.", "A family of four sits around a kitchen table playing a board game."),
 [DSM_X], card_type="clinical-focus", young="For children and teens, family conflict is one of the biggest drivers of anxiety and low mood. Keeping them out of adult arguments and giving them one steady adult to talk to protects them most."))

CARDS.append(X("child-abuse-and-neglect", "Child Abuse and Neglect", "When a child is hurt or neglected, and what helps after", ["child maltreatment", "adverse childhood experiences (ACEs)", "childhood trauma"], "T74.x / T76.x / Z62.81x / Z69.x (varies)",
 "Physical, sexual, or emotional harm, or neglect, of a child by a caregiver, and its effects at any age.",
 "Child abuse and neglect includes physical harm, sexual abuse, emotional abuse (constant criticism, threats, rejection), and neglect (not providing food, safety, care, or affection). The DSM records it both when it's happening now and as a history, because its effects can last into adulthood: anxiety, depression, PTSD, difficulty trusting, and physical health problems. It is never the child's fault. Children can be protected, and adults who were harmed as children can heal, however long ago it happened.",
 ["Nobody hit me. They just never once said a kind word. It took me until 40 to call that what it was.", "I told a teacher. She believed me. Everything that's good in my life traces back to that afternoon.", "Therapy didn't change what happened. It changed what it meant about me."],
 ["Unexplained injuries, fear of going home, flinching, or being very withdrawn or very watchful", "Hunger, poor hygiene, missing school, or being left alone too young", "Sudden changes in behaviour, sleep, or play; knowledge of sex beyond their age", "In adults: PTSD, depression, trouble trusting, shame that doesn't make sense", "A child saying something happened; always take it seriously"],
 [{"myth": "Abuse is usually by strangers.", "fact": "Most abuse is by someone the child knows and often trusts. That's why believing children and noticing changes matters more than fearing strangers."},
  {"myth": "If it was years ago, there's no point dealing with it now.", "fact": "Trauma-focused therapy helps adults at any age, and many describe it as finally setting down something they'd carried their whole life."},
  {"myth": "People who were abused become abusers.", "fact": "Most do not. Many become fiercely protective parents. The cycle is real for some, and it can be broken with support."}],
 {"plain": "Around 6 in 10 US adults report at least one adverse childhood experience, and about 1 in 6 report four or more. Abuse and neglect are among the most common.", "figure": "61% of US adults with at least one ACE; 1 in 6 with four or more (CDC BRFSS 2015–2017, 25 states)", "source_ref": "src-cdc-aces"},
 {"plain_summary": "For a child, safety comes first: child protection services, a safe adult, and medical care if needed. Then trauma-focused therapy such as TF-CBT, with a non-offending caregiver involved where possible. For adults, trauma-focused therapies (TF-CBT, EMDR, CPT) and longer-term work on trust, shame, and relationships help, along with treatment for depression, PTSD, or substance use. Peer support with other survivors reduces isolation. Any medication is prescribed and monitored by a doctor.",
  "evidence_based_options": ["Child protection and a safe environment first", "Trauma-focused CBT for children and teens, with a safe caregiver", "Trauma-focused therapies for adults: TF-CBT, EMDR, CPT, and phased therapy for complex trauma", "Treatment of co-occurring PTSD, depression, or substance use"],
  "self_help_that_supports_care": ["Telling someone, at any age; child protection and survivor helplines exist for this", "Learning about trauma responses so your reactions make sense", "Peer support with other survivors", "Going at your own pace in therapy; you set the speed"],
  "guideline_refs": ["src-cdc-aces"]},
 "If a child is in immediate danger, call emergency services. If you're worried about a child, contact a child protection helpline; you don't have to be certain. If you're a child or teen being hurt, tell a trusted adult or call a children's helpline. If you're an adult carrying this from childhood and it's affecting you now, a trauma-informed therapist can help. If you're having thoughts of ending your life, use the crisis strip.",
 "Firm but safe parenting, ordinary family arguments, and poverty on its own aren't abuse, though families under strain deserve support. Grief for a childhood that wasn't what you needed is valid even without a formal label.",
 "What was done to a child says nothing about who they are. Survivors build safe homes, deep friendships, and lives of their own making.",
 ["posttraumatic-stress-disorder", "acute-stress-disorder", "reactive-attachment-disorder", "borderline-personality-disorder", "major-depressive-disorder", "partner-violence-and-adult-abuse"],
 ["adverse-childhood-experiences", "complex-trauma", "emotional-neglect", "trauma-informed", "limits-of-confidentiality", "inner-child"],
 ["childhelp-hotline-us", "childline-uk", "nspcc-helpline-uk", "kids-helpline-australia", "reddit-r-cptsd", "rainn-hotline-us"],
 ("Soft line illustration of a child and a trusted adult sitting on school steps, the adult listening, a backpack between them, bright morning light. Pastel sky blue and yellow. No distress shown.", "A child and a trusted adult sit on school steps talking, a backpack between them."),
 [DSM_X, ACES], sens="high", notes=SAFE_MSG + ["No descriptions of abusive acts.", "Helplines for children, parents, and adult survivors all shown."], clin=True, card_type="clinical-focus",
 young="Children often don't have words for what's happening, or have been told to keep it secret. Changes in behaviour, play, sleep, or body are the language. Believe them, stay calm, and get help the same day."))

CARDS.append(X("partner-violence-and-adult-abuse", "Partner Violence and Adult Abuse", "When someone close to you is hurting or controlling you", ["domestic abuse", "intimate partner violence", "coercive control", "elder abuse"], "T74.x / T76.x / Z69.x / Z91.4x (varies)",
 "Physical, sexual, emotional, or financial abuse of an adult by a partner, family member, or carer, including control.",
 "Abuse of an adult can be physical, sexual, emotional, or financial, and it often starts with control: monitoring, isolating, belittling, threatening, or taking over money. It happens in every kind of relationship and community, to women, men, and non-binary people, including older people abused by family or carers. The DSM records it so clinicians prioritise safety. It is never the victim's fault, leaving is a process rather than a single step, and specialist services help people plan it safely.",
 ["He never hit me. He didn't need to. I wasn't allowed my own bank card, my own friends, or my own opinions.", "The helpline didn't tell me to leave. They asked what I wanted and helped me make a plan. I left eight months later, safely.", "I was 74 and my son was taking my pension. I thought nobody would believe me. They did."],
 ["A partner or family member who controls money, movement, phone, or friendships", "Fear of someone's reactions; changing your behaviour to avoid their anger", "Being hurt, threatened, forced into sex, or humiliated", "Being told you're worthless, imagining things, or that nobody else would want you", "Injuries you explain away; anxiety, depression, or sleep problems that track the relationship"],
 [{"myth": "If it were that bad, they'd just leave.", "fact": "Leaving can be the most dangerous time, and people stay for safety, money, children, immigration status, love, or hope. Specialist support makes leaving safer and more possible."},
  {"myth": "Abuse means physical violence.", "fact": "Coercive control, emotional abuse, and financial abuse can be just as damaging and are crimes in many countries. Fear is the signal, not bruises."},
  {"myth": "It doesn't happen to men, or in LGBTQ+ relationships.", "fact": "It does, and shame or lack of services keeps many from reaching out. Helplines support everyone."}],
 {"plain": "Partner violence is common: large surveys find a substantial share of women, and a smaller but significant share of men, experience it in their lifetime. Many never report it.", "figure": "Prevalence varies by country and survey; WHO estimates about 1 in 3 women worldwide experience physical or sexual violence, mostly by a partner", "source_ref": "src-dsm", "note": "Needs a primary citation (WHO 2021 estimates)."},
 {"plain_summary": "Specialist domestic abuse services offer confidential helplines, safety planning, refuge or shelter, legal advice, and advocacy, and they work with people whether or not they're ready to leave. Afterwards, trauma-focused therapy (CBT, EMDR), support groups, and treatment for depression, PTSD, or anxiety help people recover. Any medication is prescribed and monitored by a doctor. Children exposed to abuse need their own support.",
  "evidence_based_options": ["Specialist domestic abuse helplines, safety planning, and advocacy", "Refuge, shelter, and legal protection where needed", "Trauma-focused therapy after leaving: CBT, EMDR; support groups", "Treatment of PTSD, depression, or anxiety; support for children"],
  "self_help_that_supports_care": ["Calling a helpline from a safe phone; you don't have to have decided anything", "Keeping important documents and a small bag somewhere safe", "Telling one person you trust", "Using private browsing; many services have a quick-exit button"],
  "guideline_refs": []},
 "If you're in immediate danger, call emergency services. If someone is hurting, frightening, or controlling you, a domestic abuse helpline from the strip can talk through options confidentially, day or night. If you've been sexually assaulted, specialist lines and services are listed too. If you're thinking about ending your life, use the crisis strip now.",
 "Arguments, even heated ones, between equals aren't abuse. Abuse is a pattern of power and fear. Being the one who's afraid is the signal.",
 "People leave, recover, and build lives where they're safe and free. The first phone call is usually the hardest step, and it can be anonymous.",
 ["posttraumatic-stress-disorder", "major-depressive-disorder", "child-abuse-and-neglect", "family-and-relationship-problems", "intermittent-explosive-disorder"],
 ["trauma-bonding", "gaslighting", "safety-plan", "trauma-informed", "boundaries", "love-bombing"],
 ["ndvh-us", "refuge-uk", "1800respect-australia", "rainn-hotline-us", "victim-support-uk"],
 ("Soft line illustration of a person stepping through a doorway into daylight with a small bag, a friend waiting outside by a car, trees. Pastel sky blue and lavender. No threat shown.", "A person steps through a doorway into daylight with a small bag while a friend waits by a car."),
 [DSM_X], qs=["Add WHO violence against women estimates as a source."], sens="high", notes=SAFE_MSG + ["Quick-exit button and private browsing note recommended for this card.", "No descriptions of violent acts."], clin=True, card_type="clinical-focus",
 cult="Honour-based abuse, forced marriage, and abuse by in-laws or extended family are recognised forms, and immigration status is often used as a threat. Specialist services exist for these situations and keep information confidential."))

CARDS.append(X("school-and-work-problems", "School and Work Problems", "When school or work is making you unwell", ["academic problems", "occupational problems", "bullying", "burnout", "unemployment"], "Z55.x / Z56.x",
 "Problems at school or work, including bullying, burnout, failure, and job loss, that affect mental health.",
 "School and work are where most people spend their days, so trouble there hits hard. The DSM lists problems like academic failure, bullying, job loss, stressful work schedules, discrimination at work, and burnout as a focus of care, because they cause or worsen anxiety, depression, and sleep problems and are often the thing that needs changing. Burnout isn't a DSM diagnosis, but it's real and treatable. Rights to adjustments at school and work exist in many countries and are underused.",
 ["I thought I was depressed. I was being bullied by my manager. The depression lifted within weeks of leaving.", "My son's 'laziness' was dyslexia nobody had spotted. A support plan changed his whole relationship with school."],
 ["Dread on Sunday nights or before school; stomach aches, headaches, trouble sleeping", "Exhaustion, cynicism, and feeling ineffective (burnout)", "Being bullied, excluded, or discriminated against at school or work", "Falling grades, missed deadlines, or job loss, with mood dropping alongside", "Problems that ease on holidays and return at the gate"],
 [{"myth": "Burnout is just stress; push through it.", "fact": "Burnout is exhaustion plus cynicism plus feeling ineffective, from chronic unaddressed workplace stress. Pushing through deepens it. Rest, changes, and sometimes leave are needed."},
  {"myth": "Bullying is a childhood thing you grow out of.", "fact": "Workplace bullying is common and damaging. Both child and adult bullying are linked to depression and anxiety, and both have remedies."},
  {"myth": "Asking for adjustments means admitting you can't cope.", "fact": "Reasonable adjustments are a legal right in many countries and a normal part of managing a condition at school or work."}],
 {"plain": "About 1 in 5 US students aged 12 to 18 report being bullied at school in a year. Burnout figures vary widely by survey, but most full-time workers report it at least sometimes.", "figure": "19% of US students aged 12–18 bullied at school in 2021–22 (NCES); burnout estimates vary widely by definition", "source_ref": "src-nces-bullying"},
 {"plain_summary": "The most effective step is often changing the situation: a school support plan, anti-bullying action, adjustments at work, a change of role, or leave. Therapy (CBT, problem-solving therapy) helps with the anxiety, low mood, and confidence that follow, and with deciding what to do. Employee assistance programmes, school counsellors, unions, and advocacy services help with the practical side. Treating any underlying condition such as ADHD, dyslexia, anxiety, or depression often resolves 'performance' problems.",
  "evidence_based_options": ["School support plans and anti-bullying procedures", "Reasonable adjustments at work; occupational health; employee assistance programmes", "CBT or problem-solving therapy for the mental health effects", "Assessment and treatment of underlying conditions such as ADHD or dyslexia"],
  "self_help_that_supports_care": ["Keeping a written record of bullying or discrimination", "Knowing your rights; unions, advice services, and student services can help", "Protecting sleep and time off when work or study is heavy", "Talking to a tutor, manager, or HR early rather than late"],
  "guideline_refs": []},
 "If school or work is causing persistent dread, exhaustion, or low mood, or you're being bullied or discriminated against, talk to someone with power to change it (a tutor, manager, HR, union) and to a counsellor or doctor about the effects. If you're thinking about ending your life, use the crisis strip now.",
 "Ordinary exam nerves, a busy season, or not enjoying a job aren't disorders. But 'just stress' that lasts months and affects sleep and mood deserves attention.",
 "Changing the situation changes the symptoms. People leave bad jobs, get the support they needed at school, and discover the problem was never them.",
 ["adjustment-disorders", "generalized-anxiety-disorder", "major-depressive-disorder", "adhd", "specific-learning-disorder", "social-anxiety-disorder"],
 ["burnout", "reasonable-accommodations", "school-support-plans", "employee-assistance-programme", "sick-leave", "disability-rights-law"],
 ["youngminds-parents-helpline", "mind-side-by-side", "beyondblue-forums", "nami-connection-and-helpline"],
 ("Soft line illustration of a person closing a laptop at the end of the day and stepping out onto a balcony with a plant, sunset light. Pastel sky blue and coral.", "A person closes a laptop and steps out onto a balcony with a plant at sunset."),
 [DSM_X, NCES], card_type="clinical-focus", young="School refusal often has anxiety, bullying, or an unrecognised learning difficulty underneath. Early meetings with the school, and an assessment where needed, work far better than pressure."))

CARDS.append(X("housing-and-money-problems", "Housing and Money Problems", "When debt, poverty, or losing your home is the emergency", ["homelessness", "housing instability", "financial problems", "food insecurity"], "Z59.x",
 "Homelessness, unsafe or unstable housing, debt, poverty, or not having enough food, and their effect on mental health.",
 "Not having safe housing, enough money, or enough food is one of the strongest drivers of anxiety and depression, and a major barrier to recovery. The DSM lists these as a focus of care so that clinicians treat the situation, not just the symptoms. Mental health problems can also lead to money and housing trouble, in a cycle. Practical help, such as debt and housing advice, is a mental health intervention, and free services exist in every country covered here.",
 ["I didn't need antidepressants first. I needed someone to stop the eviction. Then the antidepressants made sense.", "The debt charity gave me a plan in one phone call. I slept properly for the first time in a year."],
 ["Constant worry about rent, bills, debt, or food", "Sleeping rough, sofa-surfing, or living somewhere unsafe or overcrowded", "Avoiding post, calls, or letters because of fear", "Mood, sleep, and health worsening as money gets tighter", "Skipping medication, appointments, or meals to save money"],
 [{"myth": "Money problems are a personal failing.", "fact": "Debt and housing crises mostly follow illness, job loss, relationship breakdown, or rising costs. Advice services see this every day and don't judge."},
  {"myth": "Mental health treatment should come before sorting out practical problems.", "fact": "They work together. Stabilising housing and money often does more for mood than any single therapy, and makes therapy possible."},
  {"myth": "There's no help for people who are already in debt or homeless.", "fact": "Free debt advice, housing advice, and emergency help exist in the US, UK, Canada, Australia, and India, and they can act fast."}],
 {"plain": "Mental health problems are far more common among people who are homeless or in serious debt, and money worries are one of the most common sources of stress in population surveys. There's no single prevalence figure.", "figure": "n/a", "source_ref": "src-dsm", "note": "Add a reference on mental illness prevalence in homelessness."},
 {"plain_summary": "Start with the practical: free debt advice services can negotiate with creditors and set up plans; housing advice services and homelessness helplines can prevent evictions and find emergency accommodation; benefits and welfare advice can increase income. Social workers, care coordinators, and some therapy services help with this directly. Alongside, therapy and treatment for anxiety, depression, or substance use, with any medication prescribed and monitored by a doctor, work better once the ground is steadier. Housing First approaches show that stable housing comes before, not after, recovery.",
  "evidence_based_options": ["Free debt advice and negotiated repayment plans", "Housing and homelessness advice; emergency accommodation; eviction prevention", "Benefits and welfare rights advice; social work support", "Treatment of anxiety, depression, or substance use alongside practical help"],
  "self_help_that_supports_care": ["Opening the post with someone, and calling a debt or housing line the same day", "Asking your doctor or therapist to refer you to social or welfare support", "Local food banks and community help; using them isn't failure", "Telling the people you owe money to that you're getting advice"],
  "guideline_refs": []},
 "If you're about to lose your home, can't afford food, or debts are overwhelming, call a housing or debt advice line from the list; they're free and act quickly. Tell your doctor or therapist too. If money or housing worries have you thinking about ending your life, use the crisis strip now.",
 "Budgeting stress and ordinary money worries aren't a clinical problem, though advice still helps. Mental health conditions that cause money problems, like mania or gambling disorder, have their own cards.",
 "Practical crises end. With advice and a plan, people keep their homes, clear their debts, and find their sleep and mood returning.",
 ["adjustment-disorders", "generalized-anxiety-disorder", "major-depressive-disorder", "gambling-disorder", "bipolar-i-disorder", "alcohol-use-disorder"],
 ["social-worker", "care-coordinator", "sliding-scale-fees", "stress", "crisis"],
 ["211-us", "shelter-england-helpline", "stepchange-debt-charity", "citizens-advice-adviceline", "national-debt-helpline-australia"],
 ("Soft line illustration of a person at a kitchen table with an adviser, a sorted pile of letters, a cup of tea, and a window with a view of rooftops. Pastel sky blue and olive.", "A person sits at a kitchen table with an adviser and a sorted pile of letters."),
 [DSM_X], card_type="clinical-focus"))

CARDS.append(X("social-environment-and-identity-stress", "Social Environment and Identity Stress", "Discrimination, isolation, and migration stress", ["minority stress", "discrimination", "social exclusion", "acculturation stress", "loneliness"], "Z60.x / Z65.8",
 "Stress from discrimination, exclusion, migration, isolation, or living as a minority, recorded as a focus of care.",
 "Where you live, how you're treated, and whether you belong shape mental health. The DSM lists social problems such as discrimination, social exclusion, loneliness, difficulties adjusting to a new country, and persecution as a focus of care. Research on minority stress shows that prejudice, and the constant expectation of it, raises rates of depression and anxiety among LGBTQ+ people, minorities, disabled people, and migrants. Naming the cause matters: the problem is the environment, not the person.",
 ["My therapist kept asking about my 'negative thoughts'. I kept saying: they're not thoughts, they're what happened at work on Tuesday.", "Moving countries at 15 meant losing every friend and every word I knew for feelings. Finding a community that spoke my language brought me back."],
 ["Anxiety, low mood, or hypervigilance linked to how you're treated because of who you are", "Loneliness, isolation, or no one to turn to", "Stress of migration: language, status, separation from family, loss of role", "Feeling you have to hide part of yourself to be safe", "Exhaustion from constant alertness to prejudice"],
 [{"myth": "If discrimination affects your mental health, you're too sensitive.", "fact": "Decades of research show discrimination and minority stress measurably raise rates of depression, anxiety, and physical illness. It's a stressor, not a weakness."},
  {"myth": "Loneliness is a feeling, not a health issue.", "fact": "Chronic loneliness is linked to depression, poor sleep, and physical illness. Social connection is treated as a health intervention."}],
 {"plain": "Minority stress research finds consistently higher rates of depression and anxiety among people who face prejudice. Loneliness affects a large share of adults in every country surveyed.", "figure": "Meta-analyses in Meyer (2003) found higher prevalence of mental disorders among lesbian, gay, and bisexual people, explained by stigma-related stress", "source_ref": "src-meyer-2003"},
 {"plain_summary": "Care that names the environment as the problem helps: therapy that understands minority stress, community and peer support with people who share your identity, and practical help with rights, immigration, or discrimination complaints. Treating depression, anxiety, or PTSD that result is important, with any medication prescribed and monitored by a doctor. Social prescribing, befriending, and group activities address loneliness. Clinicians can use the Cultural Formulation Interview to understand your situation in your terms.",
  "evidence_based_options": ["Culturally competent, affirming therapy that understands minority stress", "Peer and community support with people who share your identity", "Advocacy and legal help for discrimination, immigration, or persecution", "Treatment of resulting depression, anxiety, or PTSD; befriending and social prescribing for loneliness"],
  "self_help_that_supports_care": ["Finding your people: community groups, faith or cultural groups, LGBTQ+ organisations", "Limiting exposure to hostile spaces where you can, including online", "Naming what's happening to you instead of blaming yourself", "Asking for a clinician who shares or understands your background"],
  "guideline_refs": ["src-meyer-2003"]},
 "If discrimination, isolation, or the stress of migration is affecting your mood, sleep, or safety, talk to a doctor or therapist and say so plainly, and reach out to a community organisation for people in your situation. If you're being threatened or persecuted, contact the police or a specialist advocacy service. If you're thinking about ending your life, use the crisis strip now.",
 "Being different isn't a problem. Being treated badly for it is. Identity itself is never the diagnosis.",
 "Belonging is medicine. People who find their community and name their experience describe a kind of relief that no therapy alone could give.",
 ["posttraumatic-stress-disorder", "major-depressive-disorder", "generalized-anxiety-disorder", "gender-dysphoria", "culture-and-mental-health", "adjustment-disorders"],
 ["stigma", "loneliness", "person-first-identity-first", "lived-experience", "peer-support", "trauma-informed"],
 ["qlife-australia", "trevor-project", "trans-lifeline", "mind-side-by-side", "nami-connection-and-helpline"],
 ("Soft line illustration of a diverse group of people sharing food at a long table outdoors under string lights, laughing, early evening. Pastel sky blue and warm orange.", "A diverse group of people shares food at a long outdoor table under string lights."),
 [DSM_X, MEYER], card_type="clinical-focus",
 cult="Migrants and refugees may express distress through the body, through spiritual language, or through family roles rather than mood words. Interpreters, bicultural workers, and asking 'what do you call this problem?' change outcomes."))

CARDS.append(X("crime-disaster-and-legal-problems", "Crime, Disaster, and Legal Problems", "After a crime, a disaster, prison, or war", ["victim of crime", "disaster survivor", "imprisonment", "exposure to war", "legal stress"], "Z65.x",
 "Being a victim of crime, surviving a disaster or war, imprisonment, or legal trouble, as a focus of care.",
 "The DSM groups together big external events that can shape mental health: being a victim of crime or terrorism, surviving a flood, fire, or earthquake, being exposed to war, being arrested or imprisoned, or facing a court case. They're recorded so clinicians treat the context, and because effects such as PTSD, depression, anxiety, and sleep problems are common and treatable. Most people recover with time and support; some need specific help, especially after violence or long-running stress.",
 ["After the burglary I couldn't sleep in my own house. Victim support called every week until I could.", "The flood took the house. What nobody warned me about was the second year, when everyone else had moved on."],
 ["Reliving the event, nightmares, jumpiness, avoiding reminders", "Anxiety, low mood, anger, or numbness after a crime or disaster", "Ongoing stress of court cases, insurance, rebuilding, or legal processes", "Isolation or shame after prison, or fear after release", "Sleep problems and difficulty feeling safe"],
 [{"myth": "Most people who go through a disaster get PTSD.", "fact": "Most recover naturally with support. A significant minority develop PTSD or depression, and they respond well to treatment."},
  {"myth": "Legal and insurance processes are just admin, not a mental health issue.", "fact": "Drawn-out legal and financial processes after a crime or disaster are a major, measurable source of ongoing distress, often outlasting the event itself."}],
 {"plain": "After floods, around 1 in 6 to 1 in 3 survivors show PTSD depending on the study; rates after crime and war vary widely. Most people do recover.", "figure": "Pooled PTSD prevalence after floods about 15.7% (2015 review) to 29.5% (2022 review of 23 studies); about 28% after earthquakes", "source_ref": "src-flood-ptsd"},
 {"plain_summary": "In the immediate aftermath, practical support, safety, and information help most; formal 'debriefing' sessions are not recommended. Those still struggling after a month benefit from trauma-focused therapy (CBT, EMDR, CPT), and from treatment for depression or sleep problems, with any medication prescribed and monitored by a doctor. Victim support services, disaster recovery services, and advocacy help with the legal and practical burden. For people leaving prison, continuity of mental health care and housing support reduce relapse and reoffending.",
  "evidence_based_options": ["Practical support and psychological first aid early on; no mandatory debriefing", "Trauma-focused CBT, EMDR, or CPT if symptoms persist beyond a month", "Victim support, disaster recovery, and legal advocacy services", "Continuity of care and housing support after prison"],
  "self_help_that_supports_care": ["Contacting victim or disaster support services, which exist for exactly this", "Keeping routines where possible: sleep, meals, movement", "Letting people help with the practical load", "Limiting repeated exposure to news or footage of the event"],
  "guideline_refs": ["src-flood-ptsd"]},
 "If you've been through a crime, disaster, or war and symptoms are still strong after a month, or you can't function, see a doctor or a trauma-informed therapist, and contact a victim or disaster support service. If you're thinking about ending your life, use the crisis strip now.",
 "Normal upset, grief, and anger after a frightening event aren't disorders. Most people recover without treatment. Trouble sleeping for a week or two after a shock is expected.",
 "Communities rebuild, survivors recover, and people leaving prison start again. Support in the months after, not just the days, makes the difference.",
 ["posttraumatic-stress-disorder", "acute-stress-disorder", "adjustment-disorders", "major-depressive-disorder", "partner-violence-and-adult-abuse"],
 ["trauma", "trauma-informed", "hypervigilance", "startle-response", "resilience", "moral-injury"],
 ["victim-support-uk", "rainn-hotline-us", "open-arms-australia", "nami-connection-and-helpline"],
 ("Soft line illustration of neighbours rebuilding a garden fence together after a storm, tools and tea, clearing sky. Pastel sky blue and sand.", "Neighbours rebuild a garden fence together under a clearing sky."),
 [DSM_X, FLOOD], sens="elevated", notes=["No graphic event descriptions."], card_type="clinical-focus"))

CARDS.append(X("health-care-access-and-treatment-adherence", "Health Care Access and Treatment Adherence", "When getting care, or sticking with it, is the hard part", ["treatment nonadherence", "barriers to care", "unavailability of health facilities", "treatment gap"], "Z75.x / Z91.19",
 "Not being able to get care, or not following a treatment plan, recorded so the reasons can be addressed.",
 "Two things get in the way of recovery far more often than the illness itself: not being able to get care at all, and not being able to stick with it. The DSM records both as a focus of clinical attention. Barriers include cost, waiting lists, distance, stigma, and language. 'Nonadherence' covers missed medication, appointments, or therapy, and it's usually about side effects, cost, confusion, or doubt, not laziness. Both are solvable once named.",
 ["I wasn't 'non-compliant'. I was taking a drug that made me feel like a zombie and nobody had asked how it felt.", "The waiting list was 14 months. A peer support group kept me going until the therapy started."],
 ["Not being able to afford care, get an appointment, or reach a clinic", "Long waits with no support in between", "Stopping medication or therapy without telling anyone, often because of side effects", "Language, stigma, or past bad experiences keeping you away", "Confusion about what's prescribed or why"],
 [{"myth": "People who stop their medication are being difficult.", "fact": "Roughly half of people with any long-term condition don't take treatment as prescribed, usually for understandable reasons. Asking why, and adjusting, works far better than blame."},
  {"myth": "If you can't get care, there's nothing to do but wait.", "fact": "Helplines, peer groups, online programmes, sliding-scale clinics, and advocacy for faster referrals can bridge the gap."}],
 {"plain": "In many low- and middle-income countries, around 3 in 4 people with a mental health condition get no treatment at all. In high-income countries, waits and cost still leave many without care.", "figure": "76%–85% of people with mental disorders in low- and middle-income countries receive no treatment (WHO mhGAP)", "source_ref": "src-who-mhgap"},
 {"plain_summary": "For access: ask about free or sliding-scale services, telehealth, peer support, and community programmes; advocacy from a GP, social worker, or charity can speed referrals. For adherence: an honest conversation with the prescriber about side effects, cost, and doubts; simpler regimens; reminders; involving a trusted person; and shared decisions about what the treatment is for. Long-acting formulations and pharmacy support help some people. The goal is a plan the person actually agrees with.",
  "evidence_based_options": ["Shared decision-making and side-effect review with the prescriber", "Simplified regimens, reminders, and pharmacy or nurse support", "Telehealth, sliding-scale, community, and peer support options to bridge access gaps", "Advocacy and navigation help from social workers, charities, or helplines"],
  "self_help_that_supports_care": ["Telling your prescriber the truth about what you're taking and why", "Writing down questions before appointments", "Using helplines and peer groups while waiting", "Knowing your rights to care, second opinions, and interpreters"],
  "guideline_refs": ["src-who-mhgap"]},
 "If you can't get the care you need, call a mental health information line in your country; they know the routes in. If you've stopped treatment or want to, tell your prescriber rather than going silent; there's almost always an alternative. If you're in crisis while waiting, use the crisis strip.",
 "Choosing, after discussion, not to have a treatment is your right and isn't 'nonadherence'. A clinician's job is to make sure the choice is informed.",
 "Most barriers have workarounds, and most treatment problems are fixable once spoken. People who'd given up on the system find a way in, often through one good helpline call.",
 ["when-it-doesnt-fit-a-label", "medication-induced-movement-disorders", "antidepressant-discontinuation-syndrome", "schizophrenia", "major-depressive-disorder"],
 ["waitlist", "sliding-scale-fees", "telehealth", "informed-consent", "patient-rights", "second-opinion", "peer-support", "stepped-care"],
 ["nami-connection-and-helpline", "mind-side-by-side", "sane-forums-australia", "beyondblue-forums", "samhsa-national-helpline"],
 ("Soft line illustration of a person on a video call with a clinician from a kitchen, a pill organiser and a notebook on the table, morning light. Pastel sky blue and teal.", "A person talks with a clinician on a video call from their kitchen."),
 [DSM_X, MHGAP], card_type="clinical-focus"))

CARDS.append(X("other-circumstances-a-clinician-may-note", "Other Circumstances a Clinician May Note", "Caregiving, life transitions, faith, and other Z-codes", ["Z-codes", "V-codes", "psychosocial and contextual factors"], "varies",
 "A catch-all for life circumstances a clinician records as relevant: caregiving, life transitions, religious struggles, lifestyle.",
 "The DSM's final section lists dozens of circumstances that aren't disorders but matter to care: being a carer for someone ill, a phase-of-life problem such as retirement or leaving home, religious or spiritual struggles, problems related to lifestyle, wandering in dementia, and a history of self-harm or suicide attempt. There are also codes for borderline intellectual functioning and more. These codes tell the story around the symptoms, and sometimes the story is the whole point.",
 ["Caring for my husband with dementia was the hardest job I've ever had, and nobody asked how I was doing until a nurse wrote 'carer strain' in his notes.", "Leaving my faith community cost me every friend I had. My therapist treated it as the loss it was."],
 ["Exhaustion or low mood from caring for someone who's ill", "Distress around a life transition: leaving home, retirement, empty nest, a diagnosis", "Religious or spiritual struggle, loss of faith, or conflict with a community", "A history of self-harm or a suicide attempt that shapes current care", "Lifestyle factors like sleep, activity, or substance use affecting health"],
 [{"myth": "If it's not a disorder, it's not something to bring to a clinician.", "fact": "These circumstances are listed precisely so clinicians address them. Carer strain, spiritual struggle, and life transitions are common reasons people need support."},
  {"myth": "Carers should cope; it's just what family does.", "fact": "Carers have high rates of depression and burnout. Carer assessments, respite, and support groups exist and improve outcomes for both people."}],
 {"plain": "These circumstances are common; for example, a large share of adults in every country covered are unpaid carers at some point. No single figure applies.", "figure": "n/a", "source_ref": "src-dsm"},
 {"plain_summary": "Support matches the circumstance: carer assessments, respite, and carer groups; therapy for life transitions and identity change; spiritually integrated therapy or a chaplain for faith struggles where wanted; safety planning and follow-up where there's a history of self-harm or attempts; lifestyle support for sleep, movement, and substance use. The point of recording these is to make them part of the plan.",
  "evidence_based_options": ["Carer assessments, respite care, and carer support groups", "Therapy for life transitions, role loss, and identity change", "Spiritually integrated therapy or pastoral support where wanted", "Follow-up and safety planning after self-harm or a suicide attempt"],
  "self_help_that_supports_care": ["Asking to be assessed as a carer in your own right", "Naming the transition you're in; it helps to know it's a thing", "Finding others in the same situation: carers, people leaving a faith, new retirees", "Telling your clinician about history that matters, even if it's old"],
  "guideline_refs": []},
 "If caring, a life change, a spiritual crisis, or your own history is weighing on you, raise it with a doctor or therapist; it belongs in your care plan. Carer and specialist helplines exist. If you're thinking about ending your life, use the crisis strip now.",
 "Everyday life changes and ordinary doubt aren't clinical. They become a focus of care when they're causing distress or shaping treatment.",
 "Carers get rest, people find their way through transitions, and the circumstances that once felt like the whole story become one chapter.",
 ["grief-and-bereavement", "adjustment-disorders", "major-and-mild-neurocognitive-disorder", "suicidal-thoughts-and-behavior", "nonsuicidal-self-injury"],
 ["carer-rights", "resilience", "wellbeing", "self-care", "support-group"],
 ["alzheimers-association-helpline-alzconnected", "mind-side-by-side", "nami-connection-and-helpline", "sane-forums-australia"],
 ("Soft line illustration of a carer sitting in a garden with a cup of tea while a visiting nurse chats with an older relative inside, afternoon light. Pastel sky blue and lilac.", "A carer rests in a garden with tea while a nurse chats with an older relative inside."),
 [DSM_X], card_type="clinical-focus"))
